parameters.jsCode:
const body = $input.all()[0].json.body;
const ev = body.event;
if (ev !== 'shipment.created' && ev !== 'shipment.status_changed') return [{ json: { skip: true, reason: 'Not a shipment event' } }];
const s = body.data;
return [{
  json: {
    skip: false,
    event: ev,
    shipmentId: s.id,
    orderId: s.orderId,
    tenantId: s.tenantId,
    trackingNumber: s.trackingNumber,
    carrier: s.carrier,
    trackingUrl: s.trackingUrl,
    status: s.status || 'SHIPPED',
    shippedAt: s.shippedAt || new Date().toISOString()
  }
}];

